#pragma once
#include <cstdint>

// Startup checks of every hard-coded game offset in offsets.h (table generated by
// tools/offsets/gen_offset_checks.py into offsets_checks.inc). Signature Offset{}
// entries verify themselves in their constructor; this covers the plain RVA and
// field constants, which are otherwise only exercised when their feature runs.
enum class OffsetCheckKind : uint8_t
{
    Code,      // masked bytes at value + site (site = window start relative to the address)
    Data,      // masked bytes at rva site, and the dword at site + ref == module base + value
    FieldPush, // at rva site: 68 <value> 68 <&"field">
    FieldRecv, // at rva site: { &"field", value } (RecvProp name/offset pair)
};

struct OffsetCheck
{
    const char* module;
    const char* name;
    OffsetCheckKind kind;
    uint32_t value;
    int32_t site;
    int32_t ref;
    const char* pattern;
    const char* field;
};

struct OffsetModuleFingerprint
{
    const char* module;
    uint32_t timeDateStamp;
    uint32_t sizeOfImage;
};

namespace bmvr
{
    // Checks every module from the table that is loaded and not checked yet (server.dll
    // only exists once a map is loading, so call again from LevelInit). Failures are
    // logged by name and counted in Game::noteMissingOffset (the in-headset toast).
    void VerifyGameOffsets();
}
